--
-- Table structure for table `tb_evaluator_scores`
--

CREATE TABLE `tb_evaluator_scores` (
  `es_id` varchar(50) NOT NULL COMMENT 'รหัสผลคะแนนที่กรรมการให้',
  `ev_id` varchar(50) NOT NULL COMMENT 'รหัสการประเมิน (Foreign Key)',
  `e_id` varchar(50) NOT NULL COMMENT 'รหัสกรรมการ (Foreign Key)',
  `es_part1_score` int(11) DEFAULT NULL COMMENT 'คะแนนรวมส่วนที่ 1',
  `es_part2_score` int(11) DEFAULT NULL COMMENT 'คะแนนรวมส่วนที่ 2',
  `es_total_score` int(11) DEFAULT NULL COMMENT 'คะแนนรวมทั้งหมด',
  `es_strong_points` text DEFAULT NULL COMMENT 'จุดเด่นที่กรรมการให้ความเห็น',
  `es_areas_for_improvement` text DEFAULT NULL COMMENT 'จุดที่ควรพัฒนา',
  `es_comments` text DEFAULT NULL COMMENT 'ข้อคิดเห็นเพิ่มเติม'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

--
-- Dumping data for table `tb_evaluator_scores`
--

INSERT INTO `tb_evaluator_scores` (`es_id`, `ev_id`, `e_id`, `es_part1_score`, `es_part2_score`, `es_total_score`, `es_strong_points`, `es_areas_for_improvement`, `es_comments`) VALUES
('ES_68d28b714a223', 'EV_68d28b714276d', 'e68d0c219b619b', 57, 40, 97, 'นางสาวสุวิมล แซ่เตียว เป็นบุคคลที่มีการพัฒนาตนเองอย่างต่อเนื่อง เป็นแบบอย่างที่ดีแก่เพื่อนครูร่วมวิชาชีพในการทำงาน และสามารถเป็นแบบอย่างการดำเนินชีวิต มีความประพฤติตนเป็นที่เหมาะสมแก่วิชาชีพครู มีวินัยในตนเอง มีความรับผิดชอบต่องานที่ได้รับมอบหมายและเป็นแบบอย่างที่ดีให้แก่นักเรียนและผู้ร่วมงาน เป็นครูที่เสียสละ ตรงต่อเวลาพร้อมทั้งศึกษาความรู้ใหม่ใหม่มาพัฒนาตนเองอย่างต่อเนื่อง', 'ผลสัมฤทธิ์ทางการเรียนผ่านเกณฑ์ที่กำหนดร้อยละ 70 จากการจัดกระบวนการเรียนรู้แบบกระบวนการกลุ่ม และสามารถเพิ่มผลสัมฤทธิ์ให้มากขึ้นได้โดยเพิ่มกระบวนการจัดการเรียนการสอนแบบหลากหลายนขึ้นอยู่ตามศักยภาพของผู้เรียน', 'นางสาวสุวิมล แซ่เตียวเป็นผู้มีความรู้ความสามารถในด้านการจัดกระบวนการเรียนการสอนเป็นอย่างดี มีความรักและความศรัทธาในวิชาชีพครู สามารถเป็นแบบอย่างที่ดีมีความเหมาะสมในความเป็นครูที่ดีอย่างยิ่ง'),
('ES_68d296cf9b03c', 'EV_68d296cf9a9f7', 'e68d0c219b619b', 55, 40, 95, 'นางสาวสุนันทา ภักดีวณิชย์ มีความรับผิดชอบต่องานที่ได้รับมอบหมายเป็นแบบอย่างที่ดีให้แก่นักเรียนและผู้ที่ร่วมงาน มีความประพฤติตนเป็นที่เหมาะสมแก่วิชาชีพครู มีวินัยในตนเอง เป็นครูที่เสียสละตรงต่อเวลา ศึกษาความรู้ใหม่มาพัฒนาตนเองอย่างต่อเนื่อง', 'นางสาวสุนันทา ภักดีวณิชย์ มีการพัฒนาทักษะการแก้ปัญหาทางคณิตศาสตร์โดยใช้กิจกรรมการเรียนรู้แบบหลากหลายให้เหมาะสมกับผู้เรียน จึงสามารถเพิ่มผลสัมฤทธิ์ทางการเรียนได้อย่างดี', 'นางสาวสุนันทา ภักดีวณิชย์ เป็นบุคคลที่พัฒนาตนเองอย่างต่อเนื่องเป็นแบบอย่างที่ดี มีความรับผิดชอบต่องานที่ได้รับมอบหมายเป็นอย่างดี'),
('ES_68d2994a346e5', 'EV_68d2994a34140', 'e68d0c219b619b', 56, 40, 96, 'นางสาวนงนุช บุรุษพัฒน์  มีความรับผิดชอบต่องานที่ได้รับมอบหมายเป็นแบบอย่างที่ดีให้แก่นักเรียนและผู้ที่ร่วมงาน มีความประพฤติตนเป็นที่เหมาะสมแก่วิชาชีพครู มีวินัยในตนเอง เป็นครูที่เสียสละตรงต่อเวลา ศึกษาความรู้ใหม่มาพัฒนาตนเองอย่างต่อเนื่อง', 'นางสาวนงนุช บุรุษพัฒน์  สามารถใช้กระบวนการจัดกการเรียนการสอนแบบกระบวนการกลุ่ม ทำให้นักเรียนเกิดทักษะการแก้ปัญหา ทักษะการคิด ส่งผลให้เกิดการเรียนรู้และความเข้าใจในเนื้อหามากขึ้น จะส่งผลให้เพิ่มผลสัมฤทธิ์ทางการเรียนได้เป็นอย่างดี', 'นางสาวนงนุช บุรุษพัฒน์  เป็นผู้ที่มีความรู้ ความสามารถในการจัดการเรียนการสอนได้เหมาะสมตามศักยภาพของผู้เรียน มีความรักและความศรัทธาในวิชาชีพครู มีความรับผิดชอบในงานที่ได้รับมอบหมายเหมาะสมกับการแบบอย่างที่ดีให้กับนักเรียนเป็นอย่างยิ่ง'),
('ES_68d29bd3dac6b', 'EV_68d29bd3da980', 'e68d0c219b619b', 56, 40, 96, 'นายกัญญา พิลาวุธ เป็นผู้ที่การพัฒนาตนเองอย่างต่อเนื่อง มีความรับผิดชอบในงานที่ได้รับมอบหมาย มีความเสียสละและตรงต่อเวลา และเป็นแบบอย่างที่ดีให้กับนักเรียน', 'นายกัญญา พิลาวุธ มีกระบวนการจัดการเรียนการสอนที่สามารถพัฒนาผลสัมฤทธิ์ให้กับผู้เรียนตามศักยภาพของผู้เรียน จะทำให้ผลสัมฤทธิ์ทางการเรียนของผู้เรียนเพิ่มขึ้นอย่างมาก', 'นายกัญญา พิลาวุธ มีความรัก ความสรัทธาในวิชาชีพครู มีความตรงต่อเวลา มีความยุติธรรมเหมาะสมกับการเป็นแบบอย่างที่ดีอย่างยิ่ง'),
('ES_68d29eedd2976', 'EV_68d29eedd252e', 'e68d0c219b619b', 55, 40, 95, 'นางสาวบุศรินทร์ เถื่อนวรรณา มีวามรับผิดชอบในงานที่ได้รับมอบหมาย มีความเสียสละและตรงต่อเวลา มีการพัฒนาทักษะความรู้เพื่อเพิ่มศักยภาพให้แก่ผู้เรียนให้มีความรู้และสามารถนำไปใช้แก้ปัญหาสถาการณ์ต่างที่ได้พบเป็นอย่างดี', 'นางสาวบุศรินทร์ เถื่อนวรรณา  มีกระบวนการจัดการเรียนการสอนที่สามารถพัฒนาผลสัมฤทธิ์ให้กับผู้เรียนตามศักยภาพของผู้เรียน จึงส่งผลทำให้ผลสัมฤทธิ์ทางการเรียนของผู้เรียนผ่านเกณฑ์\r\nและถ้าพัฒนารูปแบบการเรียนการสอนให้นักเรียนแบบหลากหลายตามศักยภาพของผู้เรียนจะส่งผลให้ผู้เรียนผ่านเกณฑ์มาตรฐานและตัวชี้วัดเพิ่มขึ้น', 'นางสาวบุศรินทร์ เถื่อนวรรณา เป็นบุคคลที่พัฒนาตนเองอย่างต่อเนื่อง เป็นแบบอย่างที่ดี ประพฤติตนได้เหมาะสมแก่วิชาชีพครู มีความเสียสละ ประพฤติดี มีคุณธรรม จริยธรรมเป็นอย่างที่ดีต่อผู้เรียน'),
('ES_68d2a23e9834b', 'EV_68d2a23e97b51', 'e68d0c219b619b', 56, 40, 96, 'นางเจริญศรี ภู่จำรูญ  เป็นผู้ที่มีความรับผิดชอบ ความมุ่งมั่นในการทำงานและพัฒนาตนเองอย่างต่อเนื่อง มีความเสียสละรวมทั้งตรงต่อเวลา และสามารถเป็นแบบอย่างที่ดีในการดำเนินชีวิต เป็นแบบอย่างที่ดีต่อนักเรียนได้เป็นอย่างดี', 'ผลสัมฤทธิ์ทางการเรียนผ่านเกณฑ์กำหนดร้อยละ 60 ซึ่งจากการจัดกระบวนการเรียนการสอนที่ใช้กิจกรรมเพื่อนช่วนเพื่อน และการสอนซ่อมเสริมนั้นย่อมให้ผู้เรียนมีผลสัมฤทธิ์ทางการเรียนเพิ่มขึ้นมากกว่าเกณฑ์ที่กำหนดตามมาตรฐานตัวชี้วัดอย่างแน่นอน', 'นางเจริญศรี ภู่จำรูญ มีการพัฒนาตนเองอย่างต่อเนื่อง มีความเสียสละ พร้อมถ่ายทอดความรู้ให้กับผู้เรียน และเป็นแบบอย่างที่ดีต่อผู้เรียน มีความรักและความศรัทธาในวิชาชีพครู จึงเหมาะสมในความเป็นครูที่ดีและเป็นแบบ\r\nอย่างที่ดีโดยแท้จริง'),
('ES_68d34db917167', 'EV_68d34db9131db', 'e68d0c15167bc0', 50, 35, 85, '', 'การเขียนแผนการจัดการเรียนรูัให้พิจารณาเรื่องการเขียนวัตถุประสงค์', ''),
('ES_68d3567cf07d2', 'EV_68d3567cf019b', 'e68d0c15167bc0', 56, 35, 91, '', '', ''),
('ES_68d3585a08387', 'EV_68d3585a07a2c', 'e68d0c15167bc0', 58, 35, 93, '', '', ''),
('ES_68d35a8e457fa', 'EV_68d35a8e4533f', 'e68d0c15167bc0', 51, 35, 86, '', '', ''),
('ES_68d35c9d88910', 'EV_68d28b714276d', 'e68d0c15167bc0', 56, 35, 91, '', '', ''),
('ES_68d35d12c152f', 'EV_68d35d12c0ef4', 'e68d0c15167bc0', 58, 35, 93, '', '', ''),
('ES_68d360e4a1adc', 'EV_68d360e4a1742', 'e68d0c15167bc0', 52, 30, 82, '', '', ''),
('ES_68d36d1f86d46', 'EV_68d36d1f86891', 'e68d0c4213eca3', 49, 40, 89, '', 'ควรวัดและประเมินผลให้ครอบคลุมทั้งสมรรถนะและคุณลักษณะอันพึงประสงค์ที่ระบุไว้ในแผนการจัดการเรียนรู้', ''),
('ES_68d36dc4485b7', 'EV_68d36dc44804b', 'e68d0c4213eca3', 50, 40, 90, '', 'ควรวัดและประเมินผลให้ครอบคลุม (ทุกข้อ) ทั้งสมรรถนะและคุณลักษณะอันพึงประสงค์ที่ระบุไว้ในแผนการจัดการเรียนรู้', ''),
('ES_68d36e2f3a7e4', 'EV_68d36e2f3a44e', 'e68d0c4213eca3', 47, 40, 87, '', 'ควรวัดและประเมินผลให้ครอบคลุมสมรรถนะที่ระบุไว้ในแผนการจัดการเรียนรู้', ''),
('ES_68d36f6971932', 'EV_68d36f6971458', 'e68d0c4213eca3', 49, 40, 89, '', '1. ควรระบุข้อมูลในแหล่งเรียนรู้ให้ครบถ้วน เช่น วันที่ เวลาที่สืบค้น เป็นต้น\r\n2. ควรระบุตัวชี้วัดให้ครบถ้วน เช่น ด้านการพัฒนาตนเองและวิชาชีพ ในข้อย่อยที่ 3.3 การนำความรู้ ความสามารถ ทักษะที่ได้รับจากการพัฒนาตนเองและวิชาชีพมาใช้ในการจัดการเรียนรู้ การพัฒนาคุณภาพผู้เรียนและการพัฒนานวัตกรรมการจัดการเรียนรู้ เป็นต้น', ''),
('ES_68d37047b5d23', 'EV_68d37047b4e9b', 'e68d0c4213eca3', 46, 40, 86, '', '1. ควรปรับจุดประสงค์การเรียนรู้ของแผนฯ\r\n2. ควรระบุการวัดและประเมินผลให้ครอบคลุมจุดประสงค์การเรียนรู้ สมรรถนะ และคุณลักษณะอันพึงประสงค์ที่ระบุไว้ในแผนการจัดการเรียนรู้', ''),
('ES_68d37108ca4cd', 'EV_68d37108c999f', 'e68d0c4213eca3', 50, 40, 90, '', '1. ควรวัดและประเมินผลในแผนการจัดการเรียนรู้ให้ครอบคลุมสมรรถนะที่ระบุไว้\r\n2. ควรระบุตัวชี้วัดให้ครบถ้วน เช่น ด้านการพัฒนาตนเองและวิชาชีพ ในข้อย่อยที่ 3.3 การนำความรู้ ความสามารถ ทักษะที่ได้รับจากการพัฒนาตนเองและวิชาชีพมาใช้ในการจัดการเรียนรู้ การพัฒนาคุณภาพผู้เรียนและการพัฒนานวัตกรรมการจัดการเรียนรู้ เป็นต้น', ''),
('ES_68d371895a009', 'EV_68d3718959bf5', 'e68d0c4213eca3', 50, 40, 90, '', 'ควรวัดและประเมินผลให้ครอบคลุมสมรรถนะและคุณลักษณะอันพึงประสงค์ที่ระบุไว้ในแผนฯ ให้ครบถ้วน', ''),
('ES_68d371c3b8573', 'EV_68d371c3b8250', 'e68d0c4c643d04', 57, 40, 97, '', 'ผลลัพธ์ในประเด็นท้าทายหากครอบคลุมทั้ง ด้านความรู้ ทักษะ เจตคติ จะดีมากยิ่งขึ้น', ''),
('ES_68d37265e4aff', 'EV_68d37265e44b3', 'e68d0c4213eca3', 50, 40, 90, '', 'ควรปรับจุดประสงค์การเรียนรู้ของแผนฯ ให้มีความกระชับ พร้อมทั้งวัดและประเมินผลให้ครอบคลุมจุดประสงค์ สมรรถนะและคุณลักษณะอันพึงประสงค์ให้ครบถ้วน', ''),
('ES_68d373ef3b107', 'EV_68d373ef3aae9', 'e68d0c4c643d04', 56, 38, 94, '', 'ควรเขียนจุดประสงค์การเรียนรู้ในแผนการจัดการเรียนรู้ให้ครอบคลุมทั้ง K P A', ''),
('ES_68d38399780a8', 'EV_68d3839977dde', 'e68d0c4c643d04', 56, 38, 94, '', 'ควรเขียนจุดประสงค์การเรียนรู้ในแผนการจัดการเรียนรู้ให้ครอบคลุมทั้ง K P A', ''),
('ES_68d38b9d6b95b', 'EV_68d38b9d6b22a', 'e68d0c15167bc0', 56, 35, 91, '', '', ''),
('ES_68d38caf0bf4a', 'EV_68d38caf0b567', 'e68d0c4c643d04', 56, 40, 96, '', '', 'หากมีใช้เทคโนโลยี เทคนิคการสอน วิธีการสอน รูปแบบ หรือสื่ออื่น ๆ มาเพิ่มเติมอีกจะดียิ่งขึ้น'),
('ES_68d3901f09d85', 'EV_68d3901f095bd', 'e68d0c4c643d04', 56, 40, 96, '', '', 'หากมีใช้เทคโนโลยี เทคนิคการสอน วิธีการสอน รูปแบบ หรือสื่ออื่น ๆ มาเพิ่มเติมอีกจะดียิ่งขึ้น'),
