('ES_68d3adaa13892', 'EV_68d3adaa12d17', 'e68d0c4c643d04', 57, 38, 95, '', '', 'หากมีใช้เทคโนโลยี เทคนิคการสอน วิธีการสอน รูปแบบ หรือสื่ออื่น ๆ มาเพิ่มเติมอีกจะดียิ่งขึ้น'),
