('ES_68d3b77b60b32', 'EV_68d3adaa12d17', 'e68d0c57ba6a8d', 51, 33, 84, '', '', ''),
('ES_68d3b7bcf0c5c', 'EV_68d3a90b016ff', 'e68d0c57ba6a8d', 50, 33, 83, '', '', ''),
('ES_68d5074c843ff', 'EV_68d360e4a1742', 'e68d0c51e151e1', 59, 38, 97, 'เป็นผู้ที่มีความรู้ความสามารถ มุ่งมั่นพัฒนาตนเองอย่างต่อเนื่อง นำความรู้ที่มีและสื่อการสอน นวัตกรรมใหม่ ๆ มาพัฒนาการสอน', '', 'เป็นผู้ที่มีความตั้งใจในการปฏิบัติหน้าที่ เป็นผู้ที่มีคุณธรรม จริยธรรม เสียสละเพื่อส่วนรวม'),
('ES_68d50a873fb1c', 'EV_68d3abdb2a9dd', 'e68d0c51e151e1', 58, 38, 96, 'เป็นผู้ที่มีความรู้ความสามารถ นำความรู้มาประยุกต์พัฒนาการเรียนการสอน เพื่อพัฒนาการเรียน\r\nเป็นผู้ที่มีความมุ่งมั่น ตั้งใจการสอนอย่างเต็มความสามารถ', '', 'เป็นผู้ที่มีคุณธรรมจริยธรรม ปฏิบัติหน้าที่ด้วยความวิริยะอุตสาหะ\r\nมีการพัฒนาตนเองอยู่เสมอ'),
('ES_68d50bbbbdde3', 'EV_68d38b9d6b22a', 'e68d0c51e151e1', 58, 38, 96, 'เป็นผู้ที่มีความรู้ความสามารถ  มีการพัฒนาตนเองอย่างต่อเนื่อง\r\nมีการพัฒนานวัตกรรมเพื่อนำไปพัฒนาการเรียนการสอน\r\nมีความมุ่งมั่น และตั้งใจในการปฏิบัติหน้าที่\r\n', '', 'เป็นผู้ที่มีคุณธรรมจริยธรรม ปฏิบัติหน้าที่ด้วยความวิริยะอุตสาหะ\r\nเป็นผู้ทีมีจรรยาบรรณวิชาชีพครูที่ดี'),
('ES_68d50c621150d', 'EV_68d3946fdb2d0', 'e68d0c51e151e1', 58, 38, 96, 'เป็นผู้ที่มีความรู้ความสามารถ ยึดมั่นตามแบบวิชาชีพครู\r\nเป็นผู้ที่มีการพัฒนาตนเองอย่างต่อเนื่อง\r\nจัดกิจกรรมการเรียนการสอนที่หลากหลาย', '', 'เป็นผู้ที่รักและศรัทธาในวิชาชีพครู\r\nเป็นผู้ที่มีคุณธรรมจริยธรรม เป็นแบบอย่างที่ดีแก่นักเรียน'),
('ES_68d50ced2c005', 'EV_68d39823eb2a6', 'e68d0c51e151e1', 59, 38, 97, 'เป็นผู้ที่มีความรู้ความสามารถ ปฏิบัติหน้าที่ด้วยความวิริยะอุตสาหะ\r\nเป็นผู้ที่มีการจัดกิจกรรมการเรียนการสอนที่หลากหลายเหมาะสมกับผู้เรียน', '', 'เป็นผู้ที่มีคุณธรรมจริยธรรม มีความมุ่งมั่นตั้งใจในการปฏิบัติหน้าที่\r\nเป็นแบบอย่างที่ดีแก่เพื่อนครูและนักเรียน'),
